+  case T_SHORT:   // fall through
+  case T_BOOLEAN: // fall through
+  case T_BYTE:
+    return (c->as_jint() == 0);
+  case T_LONG:
+    return (c->as_jlong() == 0);
+  case T_OBJECT:  // fall through
+  case T_ARRAY:
+    return (c->as_jobject() == nullptr);
+  default:
+    return false;
+  }
+}
